次のプログラムをコンパイル、実行したときの結果として、正しいものを選びなさい。(1つ選択)

public class Main {
    public static void main(String[] args) {
        int key = 3;
        switch (key) {
            case 2:
                System.out.print("Gold");
            case 3:
                System.out.print("Silver");
            case 4:
                System.out.print("Bronze");
            default:
                System.out.print("None");
        }
    }
}

