public class Main {
    public static void main(String[] args) {
        int key = 3;
        switch (key) {
            case 2:
                System.out.print("Gold");
                break;
            case 3:
                System.out.print("Silver");
                break;
            default:
                System.out.print("None");
        }
    }
}

