public class BranchTest {
    public static void main(String[] args) {
        int val1 = 15;
        int val2 = 5;
        if(val1 >= 10 || val2 >= 10) {
            val1 /= 3;
            val2 += val1;
        } else
            val1 /= 3;
        val2 += val1;
        System.out.println(val1 + ":" + val2);
    }
}

