public class LogicB implements Operation {
    public int calc(int c, int d) {
        return (int)(2.5 * (c * d));
    }
}
public class Main {
    public static void main(String[] args) {
        Operation[] ops = {new LogicA(), new LogicB()};
        System.out.print(ops[0].calc(4, 2) + " ");
        System.out.println(ops[1].calc(4, 2));
    }
}

