次のプログラムをコンパイル、実行したときの結果として、正しいものを選びなさい。（1つ選択）

[コード]
public class Main {
    public static void main(String[] args) {
        Worker[] group = {new Developer(), new Sales(), new Developer()};
        for (Worker w : group) {
            w.work();
        }
    }
}
interface Worker {
    void work();
}
class Developer implements Worker {
    public void work() {
        System.out.println("Dev");
    }
}
class Sales {
    public void work() {
        System.out.println("Sales");
    }
}
